/** Generated by scaffold-crud-pages. Query hooks for UsageHeartbeat.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchUsageHeartbeatList,
  fetchUsageHeartbeatById,
  createUsageHeartbeat,
  updateUsageHeartbeat,
  deleteUsageHeartbeat,
  type FetchUsageHeartbeatListParams,
} from '~/services/httpServices/usageHeartbeatService';
import type { CreateUsageHeartbeatRequest, UpdateUsageHeartbeatRequest } from '~/types/usage-heartbeat';

const DOMAIN = 'usageHeartbeat';

export function useUsageHeartbeatList(params?: FetchUsageHeartbeatListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchUsageHeartbeatList(params),
  });
}

export function useUsageHeartbeat(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchUsageHeartbeatById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateUsageHeartbeat() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateUsageHeartbeatRequest) => createUsageHeartbeat(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateUsageHeartbeat() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateUsageHeartbeatRequest }) =>
      updateUsageHeartbeat(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteUsageHeartbeat() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteUsageHeartbeat(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
